def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    current_char = texto[0]
    count = 1
    for ch in texto[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = ch
            count = 1
    # add the last group
    result.append(f"{current_char}{count}")
    return "".join(result)
